function cleanJsonString(str) {
  if (!str || typeof str !== 'string') return '';

  let t = str.trim();

  // Hapus semua code fences (bisa berlapis)
  t = t.replace(/```(?:json)?\s*([\s\S]*?)```/gi, '$1').trim();
  t = t.replace(/^`+|`+$/g, '').trim();

  return t;
}

function robustParseJson(text) {
  if (!text || typeof text !== 'string') return null;

  let cleaned = cleanJsonString(text);

  // Coba 1: Parse langsung
  try { return JSON.parse(cleaned); } catch (e) {}

  // Coba 2: Bersihkan escaped quotes berlebih
  cleaned = cleaned
    .replace(/\\"/g, '"')           // \\\" → "
    .replace(/\\\\/g, '\\')         // hapus double escape
    .replace(/\n/g, ' ')            // normalisasi newline
    .replace(/\s+/g, ' ');          // normalisasi whitespace

  try { return JSON.parse(cleaned); } catch (e) {}

  // Coba 3: Ambil JSON object terbesar
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');

  if (start >= 0 && end > start) {
    let candidate = cleaned.slice(start, end + 1);
    try { 
      return JSON.parse(candidate); 
    } catch (e) {}

    // Coba bersihkan sekali lagi
    candidate = candidate.replace(/\\"/g, '"');
    try { return JSON.parse(candidate); } catch (e) {}
  }

  return null;
}

