const items = $input.all();

// Fungsi untuk mengekstrak dan mem-parsing metadata dari string pageContent
function parsePageContent(content) {
  const result = {
    nama_produk: '',
    nama_pelaku_usaha: '',
    no_sertifikat: '',
    tgl_terbit: '',
  };

  if (!content || typeof content !== 'string') return result;

  const parts = content.split('|');
  for (const part of parts) {
    const colonIdx = part.indexOf(':');
    if (colonIdx >= 0) {
      const key = part.slice(0, colonIdx).trim().toLowerCase();
      const val = part.slice(colonIdx + 1).trim();

      if (key.includes('nama produk') || key.includes('product name')) {
        result.nama_produk = val;
      } else if (key.includes('pelaku') || key.includes('company') || key.includes('manufacture')) {
        result.nama_pelaku_usaha = val;
      } else if (key.includes('tanggal terbit') || key.includes('issued')) {
        result.tgl_terbit = val;
      } else if (key.includes('sertifikat') || key.includes('cert')) {
        result.no_sertifikat = val;
      }
    }
  }
  return result;
}

function parseNumber(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string') {
    const n = Number(v.trim());
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function pickScore(obj) {
  if (!obj || typeof obj !== 'object') return null;
  const candidates = [obj.score, obj.similarity, obj._score, obj.distance];
  for (const v of candidates) {
    const n = parseNumber(v);
    if (n !== null) return n;
  }
  return null;
}

// Proses semua dokumen Qdrant ke bentuk JSON terstruktur
const parsedResults = items.map((it) => {
  const pageContent = it.json.document?.pageContent || '';
  const parsedMetadata = parsePageContent(pageContent);
  return {
    score: pickScore(it.json),
    ...parsedMetadata,
  };
});

const scores = parsedResults.map(r => r.score).filter((v) => v !== null);
