      qdrant_max_score: maxScore,
      qdrant_results: parsedResults, // Hanya berisi data murni Qdrant ter-parsing
    },
  },
];

function extractJsonText(s) {
  if (s == null) return '';
  let t = String(s).trim();
  const fence = /```(?:json)?\s*([\s\S]*?)```/i.exec(t);
  if (fence) t = fence[1].trim();
  return t;
}

function parseJsonObject(s) {
  const t = extractJsonText(s);
  if (!t) return null;
  try {
    return JSON.parse(t);
  } catch (e) {
    const start = t.indexOf('{');
    const end = t.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(t.slice(start, end + 1));
      } catch (e2) {}
    }
  }
  return null;
}

