function stableHash(obj) {
  const json = JSON.stringify(obj, Object.keys(obj).sort());
  let h1 = 2166136261 >>> 0;
  let h2 = 5381 >>> 0;
  for (let i = 0; i < json.length; i++) {
    const c = json.charCodeAt(i);
    h1 ^= c;
    h1 = Math.imul(h1, 16777619) >>> 0;
    h2 = ((h2 << 5) + h2 + c) >>> 0;
  }
  return 'fnv_' + h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0') + '_' + json.length.toString(16);
}

function pickLokalFields(row) {
  const namaProduk = row.nama_produk || '';
  const pelaku =
    typeof row.pelaku_usaha === 'string'
      ? row.pelaku_usaha
      : row.pelaku_usaha?.nama_pelaku_usaha || '';
  const noSer = row.no_sertifikat ?? row.sertifikat?.no_sertifikat ?? '';
  const tglTerbit =
    row.tgl_terbit_sertifikat ?? row.sertifikat?.tgl_terbit_sertifikat ?? '';
  const jenisProduk = row.pengajuan?.jenis_produk;
  const jenisLayanan = row.pengajuan?.jenis_layanan;
  return { namaProduk, pelaku, noSer, tglTerbit, jenisProduk, jenisLayanan };
}

const datas = $json.output.data?.datas ?? $json.data?.data?.datas ?? [];

return datas.map((row) => {
  const f = pickLokalFields(row);
  const payload = {
    source: 'bpjph_lokal_v2',
    id: row.id,
    nama_produk: row.nama_produk,
    pelaku_usaha: row.pelaku_usaha,
    pengajuan: row.pengajuan,
    sertifikat: row.sertifikat,
