    f.namaProduk ? `Nama produk: ${f.namaProduk}` : null,
    f.noSer ? `No sertifikat: ${f.noSer}` : null,
    f.tglTerbit ? `Tanggal terbit sertifikat: ${f.tglTerbit}` : null,
  ];
  if (f.jenisProduk && f.jenisProduk !== '-') {
    parts.push(`Jenis produk: ${f.jenisProduk}`);
  }
  if (f.jenisLayanan && f.jenisLayanan !== '-') {
    parts.push(`Jenis layanan: ${f.jenisLayanan}`);
  }

  const content = parts.filter(Boolean).join(' | ');

  return {
    json: {
      content,
      metadata: {
        ...payload,
        dedup_hash: stableHash(payload),
      },
      displayLine: `${f.namaProduk} — ${f.pelaku || '-'} — ${f.noSer || '-'}`,
    },
  };
});

const input = $input.first().json;

let rawText = input.output || input.text || JSON.stringify(input);

// Step 1: Hilangkan markdown code block
rawText = rawText
    .replace(/```json\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();

// Step 2: Extract JSON object yang paling luar
let parsed;

try {
    // Coba parse langsung
    parsed = JSON.parse(rawText);
} catch (e) {
    // Jika gagal, cari pola JSON dengan regex yang lebih baik
    const jsonRegex = /\{\s*"qdrant_relevancy"\s*:\s*(true|false)[\s\S]*?"final_answer"\s*:\s*"([\s\S]*?)"\s*\}/;
    const match = rawText.match(jsonRegex);

    if (match) {
        const isRelevant = match[1] === 'true';
        let finalAnswer = match[2];

        // Bersihkan escape characters di final_answer
        finalAnswer = finalAnswer
            .replace(/\\n/g, '\n')
            .replace(/\\"/g, '"')
            .replace(/\\\\/g, '\\');

        parsed = {
            qdrant_relevancy: isRelevant,
            final_answer: finalAnswer
        };
    } else {
        // Fallback
        parsed = {
            qdrant_relevancy: false,
            final_answer: rawText
        };
    }
}

// Output akhir sesuai keinginanmu
return [{
    json: {
        qdrant_relevancy: parsed.qdrant_relevancy ?? false,
        final_answer: parsed.final_answer ?? ""
    }
}];

function stableHash(obj) {
  const json = JSON.stringify(obj, Object.keys(obj).sort());
  let h1 = 2166136261 >>> 0;
  let h2 = 5381 >>> 0;
  for (let i = 0; i < json.length; i++) {
    const c = json.charCodeAt(i);
    h1 ^= c;
    h1 = Math.imul(h1, 16777619) >>> 0;
    h2 = ((h2 << 5) + h2 + c) >>> 0;
  }
  return 'fnv_' + h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0') + '_' + json.length.toString(16);
}

const datas = $json.output.data?.datas ?? $json.data?.data?.datas ?? [];

return datas.map((row) => {
  const productName = (row.product_name || '').trim();
  const payload = {
    source: 'bpjph_luar_negeri_v2',
    id: row.id,
    product_name: row.product_name,
    product_description: row.product_description,
    manufacture: row.manufacture,
    company: row.company,
    certificate: row.certificate,
    submission: row.submission,
    lhln: row.lhln,
    hs_code: row.hs_code,
    hs_code_description: row.hs_code_description,
    link: row.link,
  };

  const parts = [];
  if (productName) parts.push(`Product name: ${productName}`);
  if (row.company?.company_name) parts.push(`Company: ${row.company.company_name}`);
  if (row.company?.importer_name) parts.push(`Importer: ${row.company.importer_name}`);
  if (row.certificate?.certificate_number) {
    parts.push(`Cert: ${row.certificate.certificate_number}`);
  }
  if (row.certificate?.issued_date) {
    parts.push(`Issued: ${row.certificate.issued_date}`);
  }
  if (row.certificate?.exp_date) {
    parts.push(`Exp: ${row.certificate.exp_date}`);
  }
  const mfg = row.manufacture != null ? String(row.manufacture).trim() : '';
  if (mfg) parts.push(`Manufacture: ${mfg}`);

  const desc = (row.product_description || '').trim();
  if (desc) parts.push(`Description: ${desc}`);

  const scope = row.submission?.scope != null ? String(row.submission.scope).trim() : '';
  if (scope) parts.push(`Scope: ${scope}`);

  const subNo =
    row.submission?.submission_number != null
      ? String(row.submission.submission_number).trim()
      : '';
  if (subNo) parts.push(`Submission: ${subNo}`);

  const lhlnName = row.lhln?.name != null ? String(row.lhln.name).trim() : '';
  if (lhlnName) parts.push(`LHLN: ${lhlnName}`);

  const expMra =
    row.lhln?.exp_mra_date != null ? String(row.lhln.exp_mra_date).trim() : '';
  if (expMra) parts.push(`MRA exp: ${expMra}`);

  const hsParts = [row.hs_code, row.hs_code_description]
    .filter((x) => x != null && String(x).trim())
    .map((x) => String(x).trim());
  if (hsParts.length) parts.push(`HS: ${hsParts.join(' — ')}`);

  const link = row.link != null ? String(row.link).trim() : '';
  if (link) parts.push(`Link: ${link}`);

  const content = parts.join(' | ');

  return {
    json: {
      content,
      metadata: {
        ...payload,
        dedup_hash: stableHash(payload),
      },
      displayLine: `${productName} — ${row.company?.company_name || '-'} — ${row.certificate?.certificate_number || '-'}`,
    },
  };
});
